//! Request and response DTOs for the web gateway API.use serde::{Deserialize, Serialize};use uuid::Uuid;// --- Chat ---/// Base64-encoded image data sent from the web frontend.#[derive(Debug, Clone, Deserialize)]pub struct ImageData {    /// MIME type (e.g., "image/png", "image/jpeg").    pub media_type: String,    /// Base64-encoded image data (without data: URL prefix).    pub data: String,}#[derive(Debug, Deserialize)]pub struct SendMessageRequest {    pub content: String,    pub thread_id: Option<String>,    pub timezone: Option<String>,    /// Optional images attached to the message.    #[serde(default)]    pub images: Vec<ImageData>,}#[derive(Debug, Serialize)]pub struct SendMessageResponse {    pub message_id: Uuid,    pub status: &'static str,}#[derive(Debug, Serialize)]pub struct ThreadInfo {    pub id: Uuid,    pub state: String,    pub turn_count: usize,    pub created_at: String,    pub updated_at: String,    #[serde(skip_serializing_if = "Option::is_none")]    pub title: Option<String>,    #[serde(skip_serializing_if = "Option::is_none")]    pub thread_type: Option<String>,    #[serde(skip_serializing_if = "Option::is_none")]    pub channel: Option<String>,}#[derive(Debug, Serialize)]pub struct ThreadListResponse {    /// The pinned assistant thread (always present after first load).    pub assistant_thread: Option<ThreadInfo>,    /// Regular conversation threads.    pub threads: Vec<ThreadInfo>,    pub active_thread: Option<Uuid>,}#[derive(Debug, Serialize)]pub struct TurnInfo {    pub turn_number: usize,    pub user_input: String,    pub response: Option<String>,    pub state: String,    pub started_at: String,    pub completed_at: Option<String>,    pub tool_calls: Vec<ToolCallInfo>,}#[derive(Debug, Serialize)]pub struct ToolCallInfo {    pub name: String,    pub has_result: bool,    pub has_error: bool,    #[serde(skip_serializing_if = "Option::is_none")]    pub result_preview: Option<String>,    #[serde(skip_serializing_if = "Option::is_none")]    pub error: Option<String>,}#[derive(Debug, Serialize)]pub struct HistoryResponse {    pub thread_id: Uuid,    pub turns: Vec<TurnInfo>,    /// Whether there are older messages available.    #[serde(default)]    pub has_more: bool,    /// Cursor for the next page (ISO8601 timestamp of the oldest message returned).    #[serde(skip_serializing_if = "Option::is_none")]    pub oldest_timestamp: Option<String>,    /// Pending tool approval that needs user action (re-rendered on thread switch).    ///    /// Only populated from in-memory state; not persisted to DB.    /// Server restart clears pending approvals.    #[serde(skip_serializing_if = "Option::is_none")]    pub pending_approval: Option<PendingApprovalInfo>,}/// Lightweight DTO for a pending tool approval (excludes context_messages).#[derive(Debug, Serialize)]pub struct PendingApprovalInfo {    pub request_id: String,    pub tool_name: String,    pub description: String,    pub parameters: String,}// --- Approval ---#[derive(Debug, Deserialize)]pub struct ApprovalRequest {    pub request_id: String,    /// "approve", "always", or "deny"    pub action: String,    /// Thread that owns the pending approval (so the agent loop finds the right session).    pub thread_id: Option<String>,}// --- SSE Event Types ---#[derive(Debug, Clone, Serialize)]#[serde(tag = "type")]pub enum SseEvent {    #[serde(rename = "response")]    Response { content: String, thread_id: String },    #[serde(rename = "thinking")]    Thinking {        message: String,        #[serde(skip_serializing_if = "Option::is_none")]        thread_id: Option<String>,    },    #[serde(rename = "tool_started")]    ToolStarted {        name: String,        #[serde(skip_serializing_if = "Option::is_none")]        thread_id: Option<String>,    },    #[serde(rename = "tool_completed")]    ToolCompleted {        name: String,        success: bool,        #[serde(skip_serializing_if = "Option::is_none")]        error: Option<String>,        #[serde(skip_serializing_if = "Option::is_none")]        parameters: Option<String>,        #[serde(skip_serializing_if = "Option::is_none")]        thread_id: Option<String>,    },    #[serde(rename = "tool_result")]    ToolResult {        name: String,        preview: String,        #[serde(skip_serializing_if = "Option::is_none")]        thread_id: Option<String>,    },    #[serde(rename = "stream_chunk")]    StreamChunk {        content: String,        #[serde(skip_serializing_if = "Option::is_none")]        thread_id: Option<String>,    },    #[serde(rename = "status")]    Status {        message: String,        #[serde(skip_serializing_if = "Option::is_none")]        thread_id: Option<String>,    },    #[serde(rename = "job_started")]    JobStarted {        job_id: String,        title: String,        browse_url: String,    },    #[serde(rename = "approval_needed")]    ApprovalNeeded {        request_id: String,        tool_name: String,        description: String,        parameters: String,        #[serde(skip_serializing_if = "Option::is_none")]        thread_id: Option<String>,    },    #[serde(rename = "auth_required")]    AuthRequired {        extension_name: String,        #[serde(skip_serializing_if = "Option::is_none")]        instructions: Option<String>,        #[serde(skip_serializing_if = "Option::is_none")]        auth_url: Option<String>,        #[serde(skip_serializing_if = "Option::is_none")]        setup_url: Option<String>,    },    #[serde(rename = "auth_completed")]    AuthCompleted {        extension_name: String,        success: bool,        message: String,    },    #[serde(rename = "error")]    Error {        message: String,        #[serde(skip_serializing_if = "Option::is_none")]        thread_id: Option<String>,    },    #[serde(rename = "heartbeat")]    Heartbeat,    // Sandbox job streaming events (worker + Claude Code bridge)    #[serde(rename = "job_message")]    JobMessage {        job_id: String,        role: String,        content: String,    },    #[serde(rename = "job_tool_use")]    JobToolUse {        job_id: String,        tool_name: String,        input: serde_json::Value,    },    #[serde(rename = "job_tool_result")]    JobToolResult {        job_id: String,        tool_name: String,        output: String,    },    #[serde(rename = "job_status")]    JobStatus { job_id: String, message: String },    #[serde(rename = "job_result")]    JobResult {        job_id: String,        status: String,        #[serde(skip_serializing_if = "Option::is_none")]        session_id: Option<String>,    },    /// An image was generated by a tool.    #[serde(rename = "image_generated")]    ImageGenerated {        data_url: String,        #[serde(skip_serializing_if = "Option::is_none")]        path: Option<String>,        #[serde(skip_serializing_if = "Option::is_none")]        thread_id: Option<String>,    },    /// Suggested follow-up messages for the user.    #[serde(rename = "suggestions")]    Suggestions {        suggestions: Vec<String>,        #[serde(skip_serializing_if = "Option::is_none")]        thread_id: Option<String>,    },    /// Extension activation status change (WASM channels).    #[serde(rename = "extension_status")]    ExtensionStatus {        extension_name: String,        status: String,        #[serde(skip_serializing_if = "Option::is_none")]        message: Option<String>,    },}// --- Memory ---#[derive(Debug, Serialize)]pub struct MemoryTreeResponse {    pub entries: Vec<TreeEntry>,}#[derive(Debug, Serialize)]pub struct TreeEntry {    pub path: String,    pub is_dir: bool,}#[derive(Debug, Serialize)]pub struct MemoryListResponse {    pub path: String,    pub entries: Vec<ListEntry>,}#[derive(Debug, Serialize)]pub struct ListEntry {    pub name: String,    pub path: String,    pub is_dir: bool,    pub updated_at: Option<String>,}#[derive(Debug, Serialize)]pub struct MemoryReadResponse {    pub path: String,    pub content: String,    pub updated_at: Option<String>,}#[derive(Debug, Deserialize)]pub struct MemoryWriteRequest {    pub path: String,    pub content: String,}#[derive(Debug, Serialize)]pub struct MemoryWriteResponse {    pub path: String,    pub status: &'static str,}#[derive(Debug, Deserialize)]pub struct MemorySearchRequest {    pub query: String,    pub limit: Option<usize>,}#[derive(Debug, Serialize)]pub struct MemorySearchResponse {    pub results: Vec<SearchHit>,}#[derive(Debug, Serialize)]pub struct SearchHit {    pub path: String,    pub content: String,    pub score: f64,}// --- Jobs ---#[derive(Debug, Serialize)]pub struct JobInfo {    pub id: Uuid,    pub title: String,    pub state: String,    pub user_id: String,    pub created_at: String,    pub started_at: Option<String>,}#[derive(Debug, Serialize)]pub struct JobListResponse {    pub jobs: Vec<JobInfo>,}#[derive(Debug, Serialize)]pub struct JobSummaryResponse {    pub total: usize,    pub pending: usize,    pub in_progress: usize,    pub completed: usize,    pub failed: usize,    pub stuck: usize,}#[derive(Debug, Serialize)]pub struct JobDetailResponse {    pub id: Uuid,    pub title: String,    pub description: String,    pub state: String,    pub user_id: String,    pub created_at: String,    pub started_at: Option<String>,    pub completed_at: Option<String>,    pub elapsed_secs: Option<u64>,    #[serde(skip_serializing_if = "Option::is_none")]    pub project_dir: Option<String>,    #[serde(skip_serializing_if = "Option::is_none")]    pub browse_url: Option<String>,    #[serde(skip_serializing_if = "Option::is_none")]    pub job_mode: Option<String>,    pub transitions: Vec<TransitionInfo>,    /// Whether this job can be restarted from the UI.    #[serde(default)]    pub can_restart: bool,    /// Whether follow-up prompts can be sent to this job.    #[serde(default)]    pub can_prompt: bool,    /// The kind of job: "sandbox" or "agent".    #[serde(skip_serializing_if = "Option::is_none")]    pub job_kind: Option<String>,}// --- Project Files ---#[derive(Debug, Serialize)]pub struct ProjectFileEntry {    pub name: String,    pub path: String,    pub is_dir: bool,}#[derive(Debug, Serialize)]pub struct ProjectFilesResponse {    pub entries: Vec<ProjectFileEntry>,}#[derive(Debug, Serialize)]pub struct ProjectFileReadResponse {    pub path: String,    pub content: String,}#[derive(Debug, Serialize)]pub struct TransitionInfo {    pub from: String,    pub to: String,    pub timestamp: String,    pub reason: Option<String>,}// --- Extensions ---#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]#[serde(rename_all = "snake_case")]pub enum ExtensionActivationStatus {    Installed,    Configured,    Pairing,    Active,    Failed,}